/**
 * Utility functions for verifying Google Place IDs and constructing resilient Google Review URLs.
 */

/**
 * Determines whether a given string is a genuine, production Google Place ID.
 *
 * Synthetic place IDs generated by fallbacks/placeholders look like:
 * - "ChIJ_73120caf00000000" (starts with "ChIJ_" with an underscore)
 * - Ending in "00000000"
 * - "place_..." or "loc-..." or "dummy-..."
 *
 * Real Google Place IDs:
 * - Start with "ChIJ" followed immediately by alphanumeric characters (NEVER an underscore)
 * - Typically 27+ characters in length
 */
export function isRealGooglePlaceId(placeId?: string | null): boolean {
  if (!placeId || typeof placeId !== "string") return false;
  const trimmed = placeId.trim();

  // Synthetic hash IDs generated by fallbacks
  if (trimmed.startsWith("ChIJ_")) return false;
  if (trimmed.endsWith("00000000")) return false;
  if (
    trimmed.startsWith("place_") ||
    trimmed.startsWith("loc-") ||
    trimmed.startsWith("dummy-") ||
    trimmed.startsWith("test-")
  ) {
    return false;
  }

  // Real Google Place IDs: ChIJ + 20+ chars of [a-zA-Z0-9_-] without an underscore right after ChIJ
  if (/^ChIJ[a-zA-Z0-9-][a-zA-Z0-9_-]{18,}$/.test(trimmed)) {
    return true;
  }

  // Alternate valid Google Place ID format (e.g. starting with E... or other base64 format >= 24 chars)
  if (/^[A-Za-z0-9_-]{24,}$/.test(trimmed) && !trimmed.includes("_0000")) {
    return true;
  }

  return false;
}

/**
 * Resolves a resilient, 100% working Google Review URL for a clinic/business.
 *
 * Guaranteed NEVER to return a broken Google 404 URL like:
 * `search.google.com/local/writereview?placeid=ChIJ_73120caf00000000`
 *
 * Priority:
 * 1. If explicit custom Google URL is provided (e.g. https://g.page/r/.../review or https://maps.app.goo.gl/...),
 *    it is verified and returned.
 * 2. If a genuine real Google Place ID is present, returns the direct writereview dialog link.
 * 3. Fallback: Returns the official Google Maps Search URL (`https://www.google.com/maps/search/?api=1&query=...`),
 *    which reliably opens the business listing on Google Maps and allows writing a review with 0% chance of 404.
 */
export function resolveGoogleReviewUrl(opts: {
  placeId?: string | null;
  profileUrl?: string | null;
  businessName?: string | null;
  address?: string | null;
}): string {
  // 1. Direct custom Google review URL
  const customUrl = opts.profileUrl?.trim();
  if (customUrl && (customUrl.startsWith("http://") || customUrl.startsWith("https://"))) {
    // If the customUrl itself is an old/broken writereview URL with a synthetic ChIJ_ placeid, discard it!
    if (!customUrl.includes("placeid=ChIJ_") && !customUrl.includes("00000000")) {
      return customUrl;
    }
  }

  // 2. Genuine Google Place ID -> direct writereview dialog
  if (isRealGooglePlaceId(opts.placeId)) {
    return `https://search.google.com/local/writereview?placeid=${encodeURIComponent(opts.placeId!.trim())}`;
  }

  // 3. Fallback: Google Maps Search URL (100% reliable, never 404s)
  const name = opts.businessName?.trim() || "Clinic";
  const addr = opts.address?.trim() || "";
  const query = [name, addr].filter(Boolean).join(" ").trim() || "Clinic";
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
}

/**
 * Parses user input for Google Maps or Review links.
 * Accepts direct g.page/r/ links, maps.app.goo.gl links, google.com/maps links, or bare Place IDs.
 */
export function parsePastedGoogleUrl(input: string): {
  profileUrl: string;
  placeId?: string | null;
} {
  const trimmed = input.trim();
  let extractedPlaceId: string | null = null;

  try {
    const url = new URL(trimmed);
    const placeIdParam = url.searchParams.get("placeid") || url.searchParams.get("place_id");
    if (placeIdParam && isRealGooglePlaceId(placeIdParam)) {
      extractedPlaceId = placeIdParam;
    }
    return {
      profileUrl: trimmed,
      placeId: extractedPlaceId,
    };
  } catch {
    // If not a full URL, check if user pasted a bare Place ID
    if (isRealGooglePlaceId(trimmed)) {
      extractedPlaceId = trimmed;
      return {
        profileUrl: `https://search.google.com/local/writereview?placeid=${encodeURIComponent(trimmed)}`,
        placeId: trimmed,
      };
    }
  }

  return {
    profileUrl: trimmed,
    placeId: null,
  };
}
